INSERT INTO public.gift_card_products (product_id, face_currency, default_fulfillment_method, allowed_fulfillment_methods, redemption_instructions, terms, terms_version, expiry_months, restrictions, delivery_timing_note) VALUES ('d95c57c0-d503-5dc3-b62c-329d6422c3d1', 'SYP', 'manual', '{manual,physical_card}', 'Present the card at the checkout of any participating Demo Market branch. The cashier scans the card and deducts the purchase from its balance. The remaining balance stays on the card.', 'DRAFT — placeholder terms for demonstration. Gift cards are issued by the partner store and subject to the store''s own terms. Giftivana arranges purchase and delivery only. Cards are not redeemable for cash and cannot be reloaded. These terms require legal review before launch.', 1, 12, 'Cannot be used for tobacco, phone credit, or to buy other gift cards. Balance cannot be withdrawn as cash.', 'Arranged by the Giftivana team within 2–3 working days of payment confirmation, or on your chosen delivery date if later.') ON CONFLICT (product_id) DO NOTHING;
INSERT INTO public.gift_card_products (product_id, face_currency, default_fulfillment_method, allowed_fulfillment_methods, redemption_instructions, terms, terms_version, expiry_months, restrictions, delivery_timing_note) VALUES ('24d2ab93-0187-5d23-8463-abec56a18ad1', 'IQD', 'manual', '{manual}', 'Present the card at any till in the Demo Department Store. Partial redemption is supported; the remaining balance is printed on the receipt.', 'DRAFT — placeholder terms for demonstration. Gift cards are issued by the partner store and subject to the store''s own terms. Giftivana arranges purchase and delivery only. Cards are not redeemable for cash and cannot be reloaded. These terms require legal review before launch.', 1, NULL, 'In-store only. Not valid for online purchases or on items already discounted more than 50%.', 'Arranged by the Giftivana team within 3 working days of payment confirmation, or on your chosen delivery date if later.') ON CONFLICT (product_id) DO NOTHING;
INSERT INTO public.gift_card_products (product_id, face_currency, default_fulfillment_method, allowed_fulfillment_methods, redemption_instructions, terms, terms_version, expiry_months, restrictions, delivery_timing_note) VALUES ('e31381b7-811c-592f-8855-d11a90a8f14a', 'SYP', 'manual', '{manual,digital_code}', 'Show the code (printed or on a phone) to the cashier at any Demo Grocery Partner branch. The code can be used across several visits until the balance is spent.', 'DRAFT — placeholder terms for demonstration. Gift cards are issued by the partner store and subject to the store''s own terms. Giftivana arranges purchase and delivery only. Cards are not redeemable for cash and cannot be reloaded. These terms require legal review before launch.', 1, 6, 'Not valid for phone top-ups or utility payments made in store.', 'Arranged by the Giftivana team within 2 working days of payment confirmation. Digital codes, where offered, are sent only after the partner issues them.') ON CONFLICT (product_id) DO NOTHING;
